create function public.reserve_upload(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();pid uuid:=(p->>'postId')::uuid;mid uuid:=(p->>'messageId')::uuid;cap bigint;used bigint;n int;a public.attachments;begin perform private.require_access(s,true);perform private.learning_access();if num_nonnulls(pid,mid)<>1 then raise exception 'INVALID_PARENT';end if;if pid is not null and not exists(select 1 from public.posts where id=pid and private.group_teacher(group_id)and not deleted)then raise exception 'FORBIDDEN'using errcode='42501';end if;if mid is not null and not exists(select 1 from public.query_messages where id=mid and author_id=auth.uid()and private.can_query(query_id))then raise exception 'FORBIDDEN'using errcode='42501';end if;select storage_limit into cap from public.subscriptions where school_id=s for update;select coalesce(sum(size),0)into used from public.attachments where school_id=s and charged and state<>'deleted';if used+(p->>'size')::bigint>cap then raise exception 'STORAGE_QUOTA_EXCEEDED';end if;select count(*)into n from public.attachments where(post_id=pid or query_message_id=mid)and state<>'deleted';if n>=5 then raise exception 'MAXIMUM_FIVE_FILES';end if;insert into public.attachments(school_id,uploader_id,post_id,query_message_id,object_key,filename,declared_type,detected_type,size,checksum,charged)values(s,auth.uid(),pid,mid,s||'/'||gen_random_uuid(),p->>'filename',p->>'type',p->>'type',(p->>'size')::bigint,p->>'checksum',true)returning * into a;perform private.audit(s,'file.reserved',a.id);return jsonb_build_object('id',a.id,'objectKey',a.object_key);end$$;
create function public.complete_upload(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare a public.attachments;begin select * into a from public.attachments where id=(p->>'id')::uuid for update;if a.uploader_id<>auth.uid()or a.school_id<>private.school()then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.outbox(school_id,kind,dedup_key,payload)values(a.school_id,'scan','scan:'||a.id,jsonb_build_object('attachmentId',a.id,'objectKey',a.object_key,'checksum',a.checksum,'type',a.declared_type))on conflict do nothing;end$$;
create function public.runtime_scan_finish(p jsonb)returns void language plpgsql security definer set search_path='' as $$begin update public.attachments set state=p->>'state'where id=(p->>'id')::uuid and checksum=p->>'checksum'and state in ('quarantined','scanning','unavailable');end$$;
revoke execute on function public.reserve_upload(jsonb),public.complete_upload(jsonb),public.runtime_scan_finish(jsonb)from public,anon,authenticated;grant execute on function public.reserve_upload(jsonb),public.complete_upload(jsonb)to authenticated;grant execute on function public.runtime_scan_finish(jsonb)to service_role;
